    --form "razon_social=amniihfqcoynlazghdtqt"\
    --form "tipo_persona=Natural"\
    --form "codigo_ciiu=Suministro de electricidad, gas, vapor y aire acondicionado"\
    --form "responsabilidades_tributarias=qxbajwbpilpmufinllwlo"\
    --form "archivo=@/tmp/phpqNXPLY" </code></pre></div>


<div class="javascript-example">
