    "Accept": "application/json",
};

const body = new FormData();
body.append('municipio_id', 'consequatur');
body.append('categoria_libreta_militar', 'Primera clase');
body.append('numero_libreta_militar', 'mqeopfuudtdsufvyvddqa');
body.append('numero_distrito_militar', 'mniihfqcoynlazghdtqtq');
