};

const body = new FormData();
body.append('tipo_estudio', 'Técnico');
body.append('graduado', 'No');
body.append('institucion', 'vmqeopfuudtdsufvyvddq');
body.append('fecha_graduacion', '2026-08-07T22:16:24');
body.append('titulo_convalidado', 'Si');
body.append('fecha_convalidacion', '2026-08-07T22:16:24');
